import React, { useState } from "react";
import api from "../api";  // relative path to api.js

import toast, { Toaster } from "react-hot-toast";
import { encryptData, decryptData } from "../utils/encryption"; // ✅ using your utility
import "../styles/main.css";

export default function AdminLogin() {
  const [form, setForm] = useState({});

  const handleChange = (e) =>
    setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      // 🔐 Encrypt login form before sending
      const encryptedPayload = {
        data: encryptData(form),
      };

      const res = await api.post("/api/auth/login", encryptedPayload);

      // 🔐 Encrypt token before saving
      const encryptedToken = encryptData(res.data.token);
      localStorage.setItem("token", encryptedToken);

      toast.success("Login successful!");

      setTimeout(() => {
        window.location.href = "/admin/dashboard";
      }, 1000);
    } catch (err) {
      toast.error("Login failed!");
      console.error(err);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <Toaster />
      <h2>Admin Login</h2>

      <input
        name="username"
        placeholder="Username"
        onChange={handleChange}
        required
      />

      <input
        type="password"
        name="password"
        placeholder="Password"
        onChange={handleChange}
        required
      />

      <button type="submit">Login</button>
    </form>
  );
}
